require dirname(__DIR__).'/bootstrap.php';method('GET');$u=current_user(true);$list=rows('SELECT medalid,name,image,description FROM '.table('forum_medal').' WHERE available=1 ORDER BY displayorder,medalid');$field=one('SELECT medals FROM '.table('common_member_field_forum').' WHERE uid=?',[$u['uid']]);$own=[];foreach(explode("\t",$field['medals']??'') as $entry){$parts=explode('|',$entry);if(empty($parts[1])||(int)$parts[1]>time())$own[]=$parts[0];}foreach($list as &$m){$m['owned']=in_array((string)$m['medalid'],$own,true);$m['image']='https://www.zozse.cn/static/image/common/'.$m['image'];}unset($m);respond($list);
